package io.knowledgebrain.notification;
import org.junit.jupiter.api.Test;import java.util.*;import io.knowledgebrain.contracts.planning.delivery.v1.*;import static org.junit.jupiter.api.Assertions.*;
class DispatchEventTest {
 @Test void envelopePinsTypesProducerAndTransportAreValidated()throws Exception{var id=DispatchFixtures.ids.next();var bytes=DispatchFixtures.event(DispatchFixtures.ids.next(),id);assertNotNull(DispatchEvent.decode(bytes).source());DispatchEvent.transport(DispatchEvent.TOPIC,id.toString(),DispatchFixtures.headers(bytes),bytes);assertThrows(IllegalArgumentException.class,()->DispatchEvent.transport("planning.reminder.v1",id.toString(),DispatchFixtures.headers(bytes),bytes));var e=ReminderDeliveryEnvelopeV1.parseFrom(bytes);for(var changed:List.of(e.toBuilder().setProducer("activity-service").build(),e.toBuilder().setEventType("NotificationCreated").build(),e.toBuilder().setSpaceId("bad").build(),e.toBuilder().setActorId(DispatchFixtures.ids.next().toString()).build()))assertThrows(IllegalArgumentException.class,()->DispatchEvent.decode(changed.toByteArray()));var p=ReminderDeliveryPayloadV1.parseFrom(e.getPayload());for(var changed:List.of(p.toBuilder().setMinutesBefore(10081).build(),p.toBuilder().setRemindsOffset("+01:00").build(),p.toBuilder().setScheduleVersion(0).build(),p.toBuilder().setTriggeredAt("0001-01-01T00:00:00Z").build()))assertThrows(IllegalArgumentException.class,()->DispatchEvent.decode(e.toBuilder().setPayload(changed.toByteString()).build().toByteArray()));}
 @Test void retainedLogGapNeverSilentlyBecomesEarliest(){assertFalse(NotificationConsumer.gap(null,0,10));assertTrue(NotificationConsumer.gap(null,1,10));assertTrue(NotificationConsumer.gap(0L,1,10));assertTrue(NotificationConsumer.gap(11L,1,10));assertFalse(NotificationConsumer.gap(10L,1,10));}
}
